it('routes Fast and Quality without changing output format and keeps image requests on smart', async () => {
  const preferences = { format: 'detailed', tone: 'technical', followups: false }
  await POST(request({ question: 'Test?', preferences: { ...preferences, speed: 'fast' } }))
  expect(mocks.model).toHaveBeenLastCalledWith('fast')
  await POST(request({ question: 'Test?', preferences: { ...preferences, speed: 'quality' } }))
  expect(mocks.model).toHaveBeenLastCalledWith('smart')
  await POST(request({ question: 'Test?', image: 'data:image/png;base64,fixture', preferences: { ...preferences, speed: 'fast' } }))
  expect(mocks.model).toHaveBeenLastCalledWith('smart')
  expect(mocks.stream.mock.calls[2][0].system).toContain('DETAILED:')
})

