import type { Segment } from '@/lib/transcript/store'
import { captureSpeakerKey, captureSpeakerLabel, type CaptureSpeakerNames } from '@/lib/interview/speakerLabels'

export function CallSpeakerNames({ call, microphone, names, onChange }: {
  call: Segment[]; microphone: Segment[]; names: CaptureSpeakerNames; onChange: (key: string, name: string) => void
}) {
  const observed = [...call.map(row => ({ channel: 'call' as const, row })), ...microphone.map(row => ({ channel: 'mic' as const, row }))]
  const entries = [...new Map(observed.filter(({ row }) => row.isFinal && row.speaker != null)
    .map(item => [captureSpeakerKey(item.channel, item.row), item])).entries()].slice(0, 20)
  if (!entries.length) return null
  return <details className="border-b border-[color:var(--line)] bg-[color:var(--reader)] px-4 py-3 text-ink">
    <summary className="min-h-9 cursor-pointer py-2 text-xs font-medium">Speaker names ({entries.length})</summary>
    <p className="my-2 text-xs leading-relaxed text-[color:var(--muted)]">Labels separate voices, not verified identities. Assign a name only when you know who spoke. Names apply to the transcript, suggestions and export for this session.</p>
    <div className="space-y-2">{entries.map(([key, { channel, row }]) => <label key={key} className="block text-xs">
      {captureSpeakerLabel(channel, row)}
      <input value={names[key] ?? ''} maxLength={60} placeholder="Name or role (optional)" onChange={event => onChange(key, event.target.value)} className="mt-1 min-h-10 w-full rounded border border-[color:var(--line-strong)] bg-[color:var(--reader)] px-2 py-1.5 text-sm text-ink" />
    </label>)}</div>
  </details>
}
